import{c as t,Q as a,j as i,m as r}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"快速开始 - 5分钟完成 Hyperliquid 资产检测与找回","description":"介绍如何进入 Telegram 机器人，快速对高风险受限地址进行扫描检测，并在 5 分钟内执行第一步资产提现与找回。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/quick-start"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/quick-start"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/quick-start"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/quick-start"}],["meta",{"name":"keywords","content":"Hyperliquid快速开始, 资产恢复教程, 风险地址检测, 风控提现绕过, Telegram找回机器人"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"快速开始 - 5分钟完成 Hyperliquid 资产检测与找回"}],["meta",{"property":"og:description","content":"介绍如何进入 Telegram 机器人，快速对高风险受限地址进行扫描检测，并在 5 分钟内执行第一步资产提现与找回。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/quick-start"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"快速开始 - 5分钟完成 Hyperliquid 资产检测与找回"}],["meta",{"name":"twitter:description","content":"介绍如何进入 Telegram 机器人，快速对高风险受限地址进行扫描检测，并在 5 分钟内执行第一步资产提现与找回。"}]]},"headers":[],"relativePath":"zh/quick-start.md","filePath":"zh/quick-start.md","lastUpdated":null}'),l={name:"zh/quick-start.md"};function o(n,e,c,h,d,s){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>本页提供一条 5 分钟可执行路径，帮助您从零开始完成首轮检测与恢复。</p><p>适用场景：地址可在 Hyperliquid 前端连接，但会出现红色高风险提示层，且大部分资产操作按钮通常会受限或禁用。</p><h2 id="_1-进入机器人" tabindex="-1">1) 进入机器人 <a class="header-anchor" href="#_1-进入机器人" aria-label="Permalink to &quot;1) 进入机器人&quot;">​</a></h2><ul><li>官方入口：<a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li>或在 Telegram 搜索：<a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li>发送 <code>/start</code> 初始化会话</li></ul><h2 id="_2-先做地址检测-推荐" tabindex="-1">2) 先做地址检测（推荐） <a class="header-anchor" href="#_2-先做地址检测-推荐" aria-label="Permalink to &quot;2) 先做地址检测（推荐）&quot;">​</a></h2><ol><li>点击 <code>🔍 地址检测</code> 或发送 <code>/detect</code></li><li>输入地址（<code>0x</code> 开头，42 字符）</li><li>等待机器人扫描现货、合约、金库和质押相关资产</li><li>查看总价值、是否有等待/锁定资产，以及当前可处理的部分</li></ol><h2 id="_3-启动资产恢复" tabindex="-1">3) 启动资产恢复 <a class="header-anchor" href="#_3-启动资产恢复" aria-label="Permalink to &quot;3) 启动资产恢复&quot;">​</a></h2><ol><li>点击 <code>🛠️ 资产恢复</code> 或发送 <code>/recovery</code></li><li>输入源地址（被标记的待恢复地址）</li><li>输入私钥或助记词（仅用于本次签名）</li><li>确认恢复计划和费用明细后执行</li></ol><p>说明：如果部分资产暂时还不能处理，预览页会直接提示需要等待，而不会误显示为可以立刻处理。</p><h2 id="_4-你会看到什么" tabindex="-1">4) 你会看到什么 <a class="header-anchor" href="#_4-你会看到什么" aria-label="Permalink to &quot;4) 你会看到什么&quot;">​</a></h2><ul><li>分阶段的恢复进度展示</li><li>每一步的状态提示，告诉您是已完成、需等待、已跳过还是失败</li><li>结果页会告诉您本轮是已完成、部分完成、需要稍后再试，还是执行失败</li><li>执行摘要：恢复金额、实际费用、交易哈希</li></ul><h2 id="_5-费用口径" tabindex="-1">5) 费用口径 <a class="header-anchor" href="#_5-费用口径" aria-label="Permalink to &quot;5) 费用口径&quot;">​</a></h2><ul><li><code>Service Fee</code>：0.5%，最低 1 USDC</li><li><code>Withdrawal Fees</code>：2 USDC（两次提现）</li><li><code>Total Cost</code>：Service Fee + Withdrawal Fees</li><li><code>You Will Receive</code>：预估可恢复价值 - Total Cost</li></ul><p>详细请看 <a href="./fee-and-settlement">费用与到账</a>。</p><h2 id="_6-特殊情况" tabindex="-1">6) 特殊情况 <a class="header-anchor" href="#_6-特殊情况" aria-label="Permalink to &quot;6) 特殊情况&quot;">​</a></h2><ul><li><strong>质押资产</strong>：可能涉及等待期，机器人会给出再次执行时间。</li><li><strong>金库锁定</strong>：暂时不可提的资产会被标记为等待，解锁后再次执行即可。</li><li><strong>小额余额</strong>：受最小提现限制影响，部分步骤可能不生成。</li><li><strong>到账延迟</strong>：提现发起后资金不会立刻到达 Arbitrum，到账时间取决于 Hyperliquid 的处理速度，通常可能需要几分钟到十几分钟。</li></ul><h2 id="_7-安全检查清单" tabindex="-1">7) 安全检查清单 <a class="header-anchor" href="#_7-安全检查清单" aria-label="Permalink to &quot;7) 安全检查清单&quot;">​</a></h2><ol><li>仅使用官方机器人入口</li><li>仅在可信设备与网络操作</li><li>确认源地址在 Arbitrum 网络可正常接收资产</li><li>不截图和传播私钥/助记词</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>查看 <a href="./asset-recovery">资产恢复</a></li><li>查看 <a href="./execution-status">执行状态说明</a></li><li>查看 <a href="./faq">常见问题</a></li></ul>',21)])])}const m=t(l,[["render",o]]);export{p as __pageData,m as default};
